-- PART 02: 기준정보 테이블(TB_IDX, TB_ACCT, TB_STK)
-- 기존 계좌/종목 데이터는 보존하고, 없는 기준지수 테이블과 문서 컬럼을 추가한다.

CREATE TABLE "TB_IDX" (
    "IDX_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "IDX_CD" VARCHAR(30) NOT NULL,
    "IDX_NM" VARCHAR(150) NOT NULL,
    "IDX_NM_EN" VARCHAR(200),
    "IDX_TP" VARCHAR(30) NOT NULL,
    "MKT_CD" VARCHAR(30),
    "CNTRY_CD" VARCHAR(10) NOT NULL,
    "CURR_CD" VARCHAR(10) NOT NULL,
    "DATA_SRC_CD" VARCHAR(30) NOT NULL,
    "SRC_SYMBOL" VARCHAR(50),
    "DFLT_YN" CHAR(1) NOT NULL DEFAULT 'N',
    "USE_YN" CHAR(1) NOT NULL DEFAULT 'Y',
    "DEL_YN" CHAR(1) NOT NULL DEFAULT 'N',
    "CRT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "CRT_USR_ID" VARCHAR(50),
    "UPD_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UPD_USR_ID" VARCHAR(50),
    CONSTRAINT "PK_TB_IDX" PRIMARY KEY ("IDX_ID"),
    CONSTRAINT "UK_TB_IDX_01" UNIQUE ("IDX_CD"),
    CONSTRAINT "CK_TB_IDX_01" CHECK ("IDX_TP" IN ('MARKET','SECTOR','ETF_PROXY','BOND','COMMODITY')),
    CONSTRAINT "CK_TB_IDX_02" CHECK ("DATA_SRC_CD" IN ('KRX','YAHOO','FRED','MANUAL')),
    CONSTRAINT "CK_TB_IDX_03" CHECK ("DFLT_YN" IN ('Y','N')),
    CONSTRAINT "CK_TB_IDX_04" CHECK ("USE_YN" IN ('Y','N')),
    CONSTRAINT "CK_TB_IDX_05" CHECK ("DEL_YN" IN ('Y','N'))
);
CREATE INDEX "IDX_TB_IDX_01" ON "TB_IDX" ("IDX_TP");
CREATE INDEX "IDX_TB_IDX_02" ON "TB_IDX" ("DATA_SRC_CD", "SRC_SYMBOL");
CREATE INDEX "IDX_TB_IDX_03" ON "TB_IDX" ("USE_YN", "DEL_YN");

COMMENT ON TABLE "TB_IDX" IS '기준지수 정보';
COMMENT ON COLUMN "TB_IDX"."IDX_ID" IS '기준지수 ID';
COMMENT ON COLUMN "TB_IDX"."IDX_CD" IS '기준지수 고유 코드';
COMMENT ON COLUMN "TB_IDX"."IDX_NM" IS '기준지수명';
COMMENT ON COLUMN "TB_IDX"."IDX_NM_EN" IS '영문 기준지수명';
COMMENT ON COLUMN "TB_IDX"."IDX_TP" IS '기준지수 유형(MARKET, SECTOR, ETF_PROXY, BOND, COMMODITY)';
COMMENT ON COLUMN "TB_IDX"."MKT_CD" IS '시장 코드';
COMMENT ON COLUMN "TB_IDX"."CNTRY_CD" IS '국가 코드';
COMMENT ON COLUMN "TB_IDX"."CURR_CD" IS '통화 코드';
COMMENT ON COLUMN "TB_IDX"."DATA_SRC_CD" IS '데이터 출처 코드(KRX, YAHOO, FRED, MANUAL)';
COMMENT ON COLUMN "TB_IDX"."SRC_SYMBOL" IS '외부 데이터 수집용 심볼';
COMMENT ON COLUMN "TB_IDX"."DFLT_YN" IS '기본 기준지수 여부(Y:기본, N:일반)';
COMMENT ON COLUMN "TB_IDX"."USE_YN" IS '사용 여부(Y:사용, N:미사용)';
COMMENT ON COLUMN "TB_IDX"."DEL_YN" IS '삭제 여부(Y:삭제, N:정상)';
COMMENT ON COLUMN "TB_IDX"."CRT_DTTM" IS '생성일시';
COMMENT ON COLUMN "TB_IDX"."CRT_USR_ID" IS '생성자 ID';
COMMENT ON COLUMN "TB_IDX"."UPD_DTTM" IS '수정일시';
COMMENT ON COLUMN "TB_IDX"."UPD_USR_ID" IS '수정자 ID';

INSERT INTO "TB_IDX" ("IDX_CD","IDX_NM","IDX_NM_EN","IDX_TP","MKT_CD","CNTRY_CD","CURR_CD","DATA_SRC_CD","SRC_SYMBOL","DFLT_YN","CRT_USR_ID","UPD_USR_ID") VALUES
('KOSPI','코스피','Korea Composite Stock Price Index','MARKET','KOSPI','KR','KRW','YAHOO','^KS11','Y','SYSTEM','SYSTEM'),
('KOSDAQ','코스닥','KOSDAQ Composite Index','MARKET','KOSDAQ','KR','KRW','YAHOO','^KQ11','N','SYSTEM','SYSTEM'),
('KOSPI200','코스피200','KOSPI 200 Index','MARKET','KOSPI','KR','KRW','KRX','KOSPI200','N','SYSTEM','SYSTEM'),
('SP500','S&P500','S&P 500 Index','MARKET','NYSE','US','USD','YAHOO','^GSPC','Y','SYSTEM','SYSTEM'),
('NASDAQ100','나스닥100','NASDAQ 100 Index','MARKET','NASDAQ','US','USD','YAHOO','^NDX','N','SYSTEM','SYSTEM'),
