-- TB_ACCT를 문서의 ID 기반 기준정보 구조로 확장한다.
ALTER TABLE "TB_ACCT"
    ADD COLUMN "ACCT_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    ADD COLUMN "ACCT_CD" VARCHAR(30),
    ADD COLUMN "ACCT_NM" VARCHAR(100),
    ADD COLUMN "BRKR_CD" VARCHAR(30),
    ADD COLUMN "BRKR_NM" VARCHAR(100),
    ADD COLUMN "ACCT_NO_MASK" VARCHAR(50),
    ADD COLUMN "BASE_CURR_CD" VARCHAR(10),
    ADD COLUMN "CASH_AMT" NUMERIC(20,4),
    ADD COLUMN "RSV_CASH_AMT" NUMERIC(20,4),
    ADD COLUMN "TGT_CASH_WGT" NUMERIC(7,4),
    ADD COLUMN "DISP_SEQ" INTEGER,
    ADD COLUMN "DEL_YN" CHAR(1),
    ADD COLUMN "CRT_DTTM" TIMESTAMP WITH TIME ZONE,
    ADD COLUMN "CRT_USR_ID" VARCHAR(50),
    ADD COLUMN "UPD_DTTM" TIMESTAMP WITH TIME ZONE,
    ADD COLUMN "UPD_USR_ID" VARCHAR(50);

UPDATE "TB_ACCT" SET
    "ACCT_CD" = CASE "ACCT_TP" WHEN 'DOMESTIC' THEN 'DOMESTIC_MAIN' WHEN 'OVERSEAS' THEN 'OVERSEAS_MAIN' WHEN 'ISA' THEN 'ISA_MAIN' WHEN 'PENSION' THEN 'PENSION_MAIN' ELSE 'DOMESTIC_' || "ACCT_TP" END,
    "ACCT_NM" = CASE "ACCT_TP" WHEN 'DOMESTIC' THEN '국내계좌' WHEN 'OVERSEAS' THEN '해외계좌' WHEN 'ISA' THEN 'ISA계좌' WHEN 'PENSION' THEN '연금계좌' ELSE "ACCT_TP" || ' 계좌' END,
    "BASE_CURR_CD" = "CURR",
    "CASH_AMT" = "AVAIL_CASH",
    "RSV_CASH_AMT" = "ADD_INV_CASH",
    "TGT_CASH_WGT" = CASE "ACCT_TP" WHEN 'DOMESTIC' THEN 6 WHEN 'OVERSEAS' THEN 6 WHEN 'ISA' THEN 50 WHEN 'PENSION' THEN 14 ELSE NULL END,
    "DISP_SEQ" = CASE "ACCT_TP" WHEN 'DOMESTIC' THEN 1 WHEN 'OVERSEAS' THEN 2 WHEN 'ISA' THEN 3 WHEN 'PENSION' THEN 4 ELSE 5 END,
    "DEL_YN" = 'N', "CRT_DTTM" = "REG_DT" AT TIME ZONE 'Asia/Seoul', "UPD_DTTM" = "MOD_DT" AT TIME ZONE 'Asia/Seoul',
    "CRT_USR_ID" = 'SYSTEM', "UPD_USR_ID" = 'SYSTEM';

ALTER TABLE "TB_HOLD" ADD COLUMN "ACCT_ID" BIGINT;
UPDATE "TB_HOLD" h SET "ACCT_ID"=a."ACCT_ID" FROM "TB_ACCT" a WHERE a."ACCT_TP"=h."ACCT_TP";
ALTER TABLE "TB_HOLD" DROP CONSTRAINT "FK_ACCT_STK_01";
ALTER TABLE "TB_ACCT" DROP CONSTRAINT "pk_acct";
UPDATE "TB_ACCT" SET "ACCT_TP"='DOMESTIC' WHERE "ACCT_TP"='MIRAE';
ALTER TABLE "TB_ACCT"
    ALTER COLUMN "ACCT_CD" SET NOT NULL, ALTER COLUMN "ACCT_NM" SET NOT NULL,
    ALTER COLUMN "BASE_CURR_CD" SET NOT NULL, ALTER COLUMN "BASE_CURR_CD" SET DEFAULT 'KRW',
    ALTER COLUMN "CASH_AMT" SET NOT NULL, ALTER COLUMN "CASH_AMT" SET DEFAULT 0,
    ALTER COLUMN "RSV_CASH_AMT" SET NOT NULL, ALTER COLUMN "RSV_CASH_AMT" SET DEFAULT 0,
    ALTER COLUMN "DISP_SEQ" SET NOT NULL, ALTER COLUMN "DISP_SEQ" SET DEFAULT 0,
    ALTER COLUMN "DEL_YN" SET NOT NULL, ALTER COLUMN "DEL_YN" SET DEFAULT 'N',
    ALTER COLUMN "CRT_DTTM" SET NOT NULL, ALTER COLUMN "CRT_DTTM" SET DEFAULT CURRENT_TIMESTAMP,
    ALTER COLUMN "UPD_DTTM" SET NOT NULL, ALTER COLUMN "UPD_DTTM" SET DEFAULT CURRENT_TIMESTAMP,
    ADD CONSTRAINT "PK_TB_ACCT" PRIMARY KEY ("ACCT_ID"),
    ADD CONSTRAINT "UK_TB_ACCT_01" UNIQUE ("ACCT_CD"),
    ADD CONSTRAINT "CK_TB_ACCT_01" CHECK ("ACCT_TP" IN ('DOMESTIC','OVERSEAS','ISA','PENSION')),
    ADD CONSTRAINT "CK_TB_ACCT_02" CHECK ("BASE_CURR_CD" IN ('KRW','USD')),
    ADD CONSTRAINT "CK_TB_ACCT_03" CHECK ("CASH_AMT">=0),
    ADD CONSTRAINT "CK_TB_ACCT_04" CHECK ("RSV_CASH_AMT">=0),
    ADD CONSTRAINT "CK_TB_ACCT_05" CHECK ("TGT_CASH_WGT" IS NULL OR "TGT_CASH_WGT" BETWEEN 0 AND 100),
    ADD CONSTRAINT "CK_TB_ACCT_06" CHECK ("USE_YN" IN ('Y','N')),
    ADD CONSTRAINT "CK_TB_ACCT_07" CHECK ("DEL_YN" IN ('Y','N'));
ALTER TABLE "TB_HOLD" ADD CONSTRAINT "FK_TB_HOLD_ACCT" FOREIGN KEY ("ACCT_ID") REFERENCES "TB_ACCT"("ACCT_ID");
CREATE INDEX "IDX_TB_ACCT_01" ON "TB_ACCT" ("ACCT_TP");
CREATE INDEX "IDX_TB_ACCT_02" ON "TB_ACCT" ("USE_YN","DEL_YN");

COMMENT ON TABLE "TB_ACCT" IS '계좌 정보';
COMMENT ON COLUMN "TB_ACCT"."ACCT_ID" IS '계좌 ID'; COMMENT ON COLUMN "TB_ACCT"."ACCT_CD" IS '시스템 계좌 고유 코드';
COMMENT ON COLUMN "TB_ACCT"."ACCT_NM" IS '계좌명'; COMMENT ON COLUMN "TB_ACCT"."ACCT_TP" IS '계좌 유형(DOMESTIC:국내, OVERSEAS:해외, ISA:ISA, PENSION:연금)';
COMMENT ON COLUMN "TB_ACCT"."BRKR_CD" IS '증권사 코드'; COMMENT ON COLUMN "TB_ACCT"."BRKR_NM" IS '증권사명'; COMMENT ON COLUMN "TB_ACCT"."ACCT_NO_MASK" IS '마스킹 계좌번호';
COMMENT ON COLUMN "TB_ACCT"."BASE_CURR_CD" IS '기준 통화 코드(KRW:원화, USD:미국달러)'; COMMENT ON COLUMN "TB_ACCT"."CASH_AMT" IS '계좌 일반 현금';
COMMENT ON COLUMN "TB_ACCT"."RSV_CASH_AMT" IS '정기매수 감액 또는 중단으로 확보한 추가매수 대기현금'; COMMENT ON COLUMN "TB_ACCT"."TGT_CASH_WGT" IS '계좌 목표 현금비중(0~100)';
COMMENT ON COLUMN "TB_ACCT"."DISP_SEQ" IS '화면 표시 순번'; COMMENT ON COLUMN "TB_ACCT"."USE_YN" IS '사용 여부(Y:사용, N:미사용)'; COMMENT ON COLUMN "TB_ACCT"."DEL_YN" IS '삭제 여부(Y:삭제, N:정상)';
COMMENT ON COLUMN "TB_ACCT"."CRT_DTTM" IS '생성일시'; COMMENT ON COLUMN "TB_ACCT"."CRT_USR_ID" IS '생성자 ID'; COMMENT ON COLUMN "TB_ACCT"."UPD_DTTM" IS '수정일시'; COMMENT ON COLUMN "TB_ACCT"."UPD_USR_ID" IS '수정자 ID';

-- TB_STK를 문서 구조로 확장하고 기존 업무키 FK는 호환 유지를 위해 UNIQUE로 보존한다.
ALTER TABLE "TB_STK"
    ADD COLUMN "STK_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    ADD COLUMN "TICKER" VARCHAR(30), ADD COLUMN "STK_NM_EN" VARCHAR(200), ADD COLUMN "CNTRY_CD" VARCHAR(10),
    ADD COLUMN "CURR_CD" VARCHAR(10), ADD COLUMN "AST_TP" VARCHAR(30), ADD COLUMN "STK_GRADE" VARCHAR(20),
    ADD COLUMN "BASE_IDX_ID" BIGINT, ADD COLUMN "SECT_CD" VARCHAR(30), ADD COLUMN "SECT_NM" VARCHAR(100),
    ADD COLUMN "INDST_CD" VARCHAR(30), ADD COLUMN "INDST_NM" VARCHAR(100),
    ADD COLUMN "REG_BUY_YN" CHAR(1) DEFAULT 'Y', ADD COLUMN "ADD_BUY_YN" CHAR(1) DEFAULT 'Y', ADD COLUMN "REBUY_YN" CHAR(1) DEFAULT 'Y',
    ADD COLUMN "FUND_DMG_YN" CHAR(1) DEFAULT 'N', ADD COLUMN "THEME_RISK_YN" CHAR(1) DEFAULT 'N',
    ADD COLUMN "USE_YN" CHAR(1) DEFAULT 'Y', ADD COLUMN "DEL_YN" CHAR(1) DEFAULT 'N',
    ADD COLUMN "CRT_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "CRT_USR_ID" VARCHAR(50),
    ADD COLUMN "UPD_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "UPD_USR_ID" VARCHAR(50);
UPDATE "TB_STK" SET "TICKER"="STK_CD", "CNTRY_CD"=CASE WHEN "MKT_CD"='KO' THEN 'KR' ELSE 'US' END,
    "CURR_CD"=COALESCE("CURR",CASE WHEN "MKT_CD"='KO' THEN 'KRW' ELSE 'USD' END), "AST_TP"=COALESCE("ASSET_TP",'STOCK'),
    "STK_GRADE"=COALESCE((SELECT ss."STK_GRD" FROM "TB_STK_SET" ss WHERE ss."MKT_CD"="TB_STK"."MKT_CD" AND ss."STK_CD"="TB_STK"."STK_CD" AND ss."STK_GRD" IN ('CORE','SATELLITE','THEME') LIMIT 1),'CORE'),
    "USE_YN"="ACTV_YN", "DEL_YN"='N', "CRT_DTTM"="REG_DT" AT TIME ZONE 'Asia/Seoul', "UPD_DTTM"="MOD_DT" AT TIME ZONE 'Asia/Seoul', "CRT_USR_ID"='SYSTEM', "UPD_USR_ID"='SYSTEM';
DROP VIEW tb_hold;
ALTER TABLE "TB_HOLD" DROP CONSTRAINT "FK_ACCT_STK_02";
ALTER TABLE "TB_PRC_DAY" DROP CONSTRAINT "FK_STK_PRC_01";
ALTER TABLE "TB_STK" DROP CONSTRAINT "PK_STK";
ALTER TABLE "TB_STK"
    ALTER COLUMN "STK_NM" TYPE VARCHAR(150), ALTER COLUMN "MKT_CD" TYPE VARCHAR(30),
    ALTER COLUMN "TICKER" SET NOT NULL, ALTER COLUMN "CNTRY_CD" SET NOT NULL, ALTER COLUMN "CURR_CD" SET NOT NULL,
    ALTER COLUMN "AST_TP" SET NOT NULL, ALTER COLUMN "STK_GRADE" SET NOT NULL,
    ALTER COLUMN "REG_BUY_YN" SET NOT NULL, ALTER COLUMN "ADD_BUY_YN" SET NOT NULL, ALTER COLUMN "REBUY_YN" SET NOT NULL,
    ALTER COLUMN "FUND_DMG_YN" SET NOT NULL, ALTER COLUMN "THEME_RISK_YN" SET NOT NULL, ALTER COLUMN "USE_YN" SET NOT NULL,
    ALTER COLUMN "DEL_YN" SET NOT NULL, ALTER COLUMN "CRT_DTTM" SET NOT NULL, ALTER COLUMN "UPD_DTTM" SET NOT NULL,
    ADD CONSTRAINT "PK_TB_STK" PRIMARY KEY ("STK_ID"), ADD CONSTRAINT "UK_TB_STK_01" UNIQUE ("STK_CD"),
    ADD CONSTRAINT "UK_TB_STK_02" UNIQUE ("TICKER","MKT_CD"), ADD CONSTRAINT "UK_TB_STK_LEGACY" UNIQUE ("MKT_CD","STK_CD"),
    ADD CONSTRAINT "FK_TB_STK_01" FOREIGN KEY ("BASE_IDX_ID") REFERENCES "TB_IDX"("IDX_ID"),
    ADD CONSTRAINT "CK_TB_STK_01" CHECK ("AST_TP" IN ('STOCK','ETF','BOND_ETF','COMMODITY_ETF','CASH_EQUIVALENT')),
    ADD CONSTRAINT "CK_TB_STK_02" CHECK ("STK_GRADE" IN ('CORE','SATELLITE','THEME')),
    ADD CONSTRAINT "CK_TB_STK_03" CHECK ("REG_BUY_YN" IN ('Y','N')), ADD CONSTRAINT "CK_TB_STK_04" CHECK ("ADD_BUY_YN" IN ('Y','N')),
    ADD CONSTRAINT "CK_TB_STK_05" CHECK ("REBUY_YN" IN ('Y','N')), ADD CONSTRAINT "CK_TB_STK_06" CHECK ("FUND_DMG_YN" IN ('Y','N')),
    ADD CONSTRAINT "CK_TB_STK_07" CHECK ("THEME_RISK_YN" IN ('Y','N')), ADD CONSTRAINT "CK_TB_STK_08" CHECK ("USE_YN" IN ('Y','N')),
    ADD CONSTRAINT "CK_TB_STK_09" CHECK ("DEL_YN" IN ('Y','N'));
ALTER TABLE "TB_HOLD" ADD CONSTRAINT "FK_TB_HOLD_STK" FOREIGN KEY ("MKT_CD","STK_CD") REFERENCES "TB_STK"("MKT_CD","STK_CD") ON DELETE CASCADE;
ALTER TABLE "TB_PRC_DAY" ADD CONSTRAINT "FK_TB_PRC_DAY_STK" FOREIGN KEY ("MKT_CD","STK_CD") REFERENCES "TB_STK"("MKT_CD","STK_CD") ON DELETE CASCADE;
CREATE VIEW tb_hold AS
SELECT a."ACCT_TP" AS market_scope, s."STK_CD" AS stock_code,
       s."STK_NM" AS stock_name, s."LIST_SCOPE" AS listing_scope,
       s."ASSET_TP" AS asset_type, s."EXCH_NM" AS exchange_name,
       s."CURR" AS currency, s."PRVDR" AS provider, s."ACTV_YN" AS active_yn,
       a."REG_DT" AS created_at, a."MOD_DT" AS updated_at,
       a."QTY" AS qty, a."AVG_PRC" AS avg_prc
FROM "TB_HOLD" a
JOIN "TB_STK" s ON s."MKT_CD"=a."MKT_CD" AND s."STK_CD"=a."STK_CD";
CREATE INDEX "IDX_TB_STK_01" ON "TB_STK" ("MKT_CD","TICKER"); CREATE INDEX "IDX_TB_STK_02" ON "TB_STK" ("STK_GRADE");
CREATE INDEX "IDX_TB_STK_03" ON "TB_STK" ("BASE_IDX_ID"); CREATE INDEX "IDX_TB_STK_04" ON "TB_STK" ("USE_YN","DEL_YN");

COMMENT ON TABLE "TB_STK" IS '종목 정보';
COMMENT ON COLUMN "TB_STK"."STK_ID" IS '종목 ID'; COMMENT ON COLUMN "TB_STK"."STK_CD" IS '시스템 종목 고유 코드'; COMMENT ON COLUMN "TB_STK"."TICKER" IS '거래소 종목코드 또는 해외 티커';
COMMENT ON COLUMN "TB_STK"."STK_NM" IS '종목명'; COMMENT ON COLUMN "TB_STK"."STK_NM_EN" IS '영문 종목명'; COMMENT ON COLUMN "TB_STK"."MKT_CD" IS '시장 코드';
COMMENT ON COLUMN "TB_STK"."CNTRY_CD" IS '국가 코드'; COMMENT ON COLUMN "TB_STK"."CURR_CD" IS '거래 통화 코드'; COMMENT ON COLUMN "TB_STK"."AST_TP" IS '자산 유형(STOCK, ETF, BOND_ETF, COMMODITY_ETF, CASH_EQUIVALENT)';
COMMENT ON COLUMN "TB_STK"."STK_GRADE" IS '종목등급(CORE:핵심, SATELLITE:위성, THEME:테마)'; COMMENT ON COLUMN "TB_STK"."BASE_IDX_ID" IS '기준지수 ID';
COMMENT ON COLUMN "TB_STK"."SECT_CD" IS '섹터 코드'; COMMENT ON COLUMN "TB_STK"."SECT_NM" IS '섹터명'; COMMENT ON COLUMN "TB_STK"."INDST_CD" IS '산업 코드'; COMMENT ON COLUMN "TB_STK"."INDST_NM" IS '산업명';
COMMENT ON COLUMN "TB_STK"."REG_BUY_YN" IS '정기매수 가능 여부(Y:가능, N:불가)'; COMMENT ON COLUMN "TB_STK"."ADD_BUY_YN" IS '추가매수 가능 여부(Y:가능, N:불가)'; COMMENT ON COLUMN "TB_STK"."REBUY_YN" IS '재매수 가능 여부(Y:가능, N:불가)';
COMMENT ON COLUMN "TB_STK"."FUND_DMG_YN" IS '펀더멘털 훼손 여부(Y:훼손, N:정상)'; COMMENT ON COLUMN "TB_STK"."THEME_RISK_YN" IS '테마 위험 여부(Y:위험, N:정상)';
COMMENT ON COLUMN "TB_STK"."USE_YN" IS '사용 여부(Y:사용, N:미사용)'; COMMENT ON COLUMN "TB_STK"."DEL_YN" IS '삭제 여부(Y:삭제, N:정상)';
COMMENT ON COLUMN "TB_STK"."CRT_DTTM" IS '생성일시'; COMMENT ON COLUMN "TB_STK"."CRT_USR_ID" IS '생성자 ID'; COMMENT ON COLUMN "TB_STK"."UPD_DTTM" IS '수정일시'; COMMENT ON COLUMN "TB_STK"."UPD_USR_ID" IS '수정자 ID';

